import {schedule,parseWords,normalize,dateKey,streak} from './engine.js';
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const seeds=[
 ['resilient','qiyinchilikdan tez tiklanadigan','She remained resilient in the face of adversity.','IELTS Essential','B2'],
 ['ubiquitous','hamma joyda uchraydigan','Smartphones have become ubiquitous.','IELTS Essential','C1'],
 ['substantial','sezilarli; katta','The project requires substantial investment.','IELTS Essential','B2'],
 ['consequently','natijada; shu sababli','It rained heavily; consequently, the match was cancelled.','IELTS Essential','B2'],
 ['sustainable','barqaror; uzoq davom eta oladigan','We need more sustainable sources of energy.','IELTS Essential','B2'],
 ['meticulous','juda sinchkov','She is meticulous about her research.','IELTS Essential','C1'],
 ['achieve','erishmoq','You can achieve your goals with practice.','Everyday English','B1'],
 ['improve','yaxshilamoq','Reading helps improve your vocabulary.','Everyday English','A2'],
 ['opportunity','imkoniyat','This is a great opportunity to learn.','Everyday English','B1'],
 ['confident','o‘ziga ishongan','I feel more confident when I practise.','Everyday English','B1'],
 ['take into account','hisobga olmoq','We must take the cost into account.','Academic Collocations','B2'],
 ['play a vital role','muhim rol o‘ynamoq','Education plays a vital role in society.','Academic Collocations','B2'],
 ['draw a conclusion','xulosa chiqarmoq','We can draw a conclusion from these results.','Academic Collocations','B2'],
 ['conduct research','tadqiqot o‘tkazmoq','Scientists conduct research to test ideas.','Academic Collocations','B2']
];
const blank=()=>({version:1,name:'O‘rganuvchi',goal:10,xp:0,log:{},spell:{right:0,total:0},completed:[],cards:seeds.map(([word,translation,example,deck,level])=>({id:uid(),word,translation,example,deck,level,due:0,reps:0,reviews:0,interval:0,ease:2.5}))});
let state,storageOK=true;
try{const raw=localStorage.getItem('lexora.v1');state=raw?JSON.parse(raw):blank();if(!state||state.version!==1||!Array.isArray(state.cards)||!state.log||!state.spell)throw Error();}catch{state=blank();}
let route='home',search='',deckFilter='',session=null,spelling=null,showBack=false,toastTimer;
const nav=[['home','⌂','Bosh sahifa'],['vocab','▤','Lug‘at & SRS','ANKI'],['spell','⌨','Imlo mashqi'],['courses','◫','Mini darslar'],['analytics','◷','Natijalar'],['telegram','➤','Telegram'],['designs','◇','Dizaynlar'],['settings','⚙','Sozlamalar']];
const btn=(text,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${text}</button>`;
const due=()=>state.cards.filter(c=>c.due<=Date.now());
const today=()=>state.log[dateKey()]||0;
const decks=()=>[...new Set(state.cards.map(c=>c.deck))];
function save(){try{localStorage.setItem('lexora.v1',JSON.stringify(state));}catch{storageOK=false;toast('Saqlash uchun brauzer xotirasi yetarli emas. Zaxira nusxasini yuklab oling.');}updateHeader();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function updateHeader(){$('#xp').textContent=`ϟ ${state.xp} XP`;$('#streak').textContent=`♨ ${streak(state.log)} kun`;$('#profile-name').innerHTML=`${e(state.name)}<small>Mustaqil o‘rganuvchi</small>`;}
function heading(label,title,sub,right=''){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${sub}</p></div>${right}</div>`;}
function stat(icon,value,label){return `<div class="stat"><span class="stat-icon">${icon}</span><div class="num">${value}<small>${label}</small></div></div>`;}
function deckRows(){return decks().map((name,i)=>{const cards=state.cards.filter(c=>c.deck===name),n=cards.filter(c=>c.due<=Date.now()).length,pct=Math.round(cards.filter(c=>c.reps>0).length/cards.length*100);return `<div class="deck"><span class="deck-icon">${['▤','Aa','✦'][i%3]}</span><div class="deck-copy"><h3>${e(name)}</h3><small>${cards.length} so‘z · ${n} ta takrorlash uchun</small><div class="progress"><span style="width:${pct}%"></span></div></div><button class="btn" data-study="${e(name)}">O‘rganish ↗</button></div>`;}).join('')||'<div class="empty">Birinchi so‘zingizni qo‘shing.</div>';}
function home(){const learned=state.cards.filter(c=>c.reps>0).length;return heading('SHAXSIY O‘QUV MAYDONI',`Salom, ${e(state.name)} <span style="color:var(--purple)">✦</span>`,'Bugungi kichik qadamingiz — ertangi katta natijangiz.','<span class="pill">● O‘rganish uchun ajoyib kun</span>')+`<section class="hero"><div class="hero-content"><span class="eyebrow" style="color:#c1a9ff">BILIMINGIZNI KEYINGI BOSQICHGA OLIB CHIQING</span><h2>So‘zlarni yodlamang.<br><em>Ularni o‘zlashtiring.</em></h2><p>Aqlli takrorlash, qisqa mashqlar va har kungi o‘sish. Ingliz tilini o‘rganish endi o‘zingizga mos ritmda.</p><div class="buttons">${btn('ϟ Mashg‘ulotni boshlash','study','primary')}${btn('＋ So‘z qo‘shish','add')}</div></div><div class="hero-art"><div class="orbit"></div><img class="owl-art" src="assets/owl.png" alt="Lexora neon boyo‘g‘li"><div class="float-tag one">✦ Bilim — sizning superkuchingiz</div><div class="float-tag two">ϟ Har bir mashq uchun +10 XP</div></div></section><div class="stats">${stat('▤',state.cards.length,'Jami so‘zlar')}${stat('↻',due().length,'Takrorlash vaqti keldi')}${stat('♨',streak(state.log),'Kunlik ketma-ketlik')}${stat('✧',learned,'O‘rganilayotgan so‘zlar')}</div><div class="grid"><section class="panel"><div class="section-head"><h2>So‘z to‘plamlaringiz</h2><button class="text-btn" data-route="vocab">Barchasini ko‘rish ↗</button></div>${deckRows()}</section><section class="panel"><div class="section-head"><h2>Bugungi maqsad</h2><span class="tag">${new Date().toLocaleDateString('uz-UZ',{day:'numeric',month:'short'})}</span></div><div class="daily-ring" style="--angle:${Math.min(100,today()/state.goal*100)*3.6}deg"><div><strong>${today()}<span class="muted" style="font-size:16px"> / ${state.goal}</span></strong><small>kartochka takrorlandi</small></div></div><div class="goal-row"><span>Bugungi tajriba</span><b>+${today()*10} XP</b></div><div class="week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return `<div class="day ${state.log[dateKey(d)]?'done':''}"><span>${state.log[dateKey(d)]?'✓':d.getDate()}</span>${d.toLocaleDateString('uz-UZ',{weekday:'short'})}</div>`;}).join('')}</div></section></div><div class="tip"><span class="icon">✦</span><div><h3>Ko‘proq emas, muntazam o‘rganing.</h3><p>Har kuni 10 daqiqalik takrorlash so‘zlarni uzoq muddatli xotiraga ko‘chirishga yordam beradi.</p></div><button class="text-btn" data-route="spell" style="margin-left:auto;white-space:nowrap">Imlo mashqi ↗</button></div>`;}
function vocab(){return heading('SO‘Z BOYLIGINGIZ','Lug‘at & SRS','So‘zlaringizni boshqaring va vaqti kelganda takrorlang.')+`<div class="toolbar"><input id="search" type="search" placeholder="So‘z yoki tarjimani qidirish…" value="${e(search)}" aria-label="So‘z qidirish"><select id="deck-filter" aria-label="To‘plam"><option value="">Barcha to‘plamlar</option>${decks().map(d=>`<option ${d===deckFilter?'selected':''}>${e(d)}</option>`).join('')}</select>${btn('＋ Yangi so‘z','add','primary')}${btn('↥ Import','import')}${btn('↻ Takrorlash','study','cyan')}</div><section class="panel table-wrap" id="word-table">${wordTable()}</section><p style="font-size:11px">Takrorlash usuli: soddalashtirilgan SM-2. Bahoga qarab keyingi takrorlash vaqti hisoblanadi. FSRS emas.</p>`;}
function wordTable(){const cards=state.cards.filter(c=>(!deckFilter||c.deck===deckFilter)&&normalize(c.word+' '+c.translation).includes(normalize(search)));return `<table><thead><tr><th>SO‘Z / IBORA</th><th>TARJIMA</th><th>TO‘PLAM</th><th>HOLAT</th><th>AMALLAR</th></tr></thead><tbody>${cards.map(c=>`<tr><td>${e(c.word)} <span class="tag">${e(c.level)}</span><small>${e(c.example)}</small></td><td>${e(c.translation)}</td><td>${e(c.deck)}</td><td><span class="tag ${c.due>Date.now()?'green':''}">${c.due>Date.now()?new Date(c.due).toLocaleDateString('uz-UZ'):c.reviews?'Takrorlash':'Yangi'}</span></td><td><button class="icon-btn" data-audio="${e(c.word)}" aria-label="Talaffuz">♫</button> <button class="icon-btn" data-edit="${c.id}" aria-label="Tahrirlash">✎</button> <button class="icon-btn" data-delete="${c.id}" aria-label="O‘chirish">×</button></td></tr>`).join('')}</tbody></table>${cards.length?'':`<div class="empty">Mos so‘z topilmadi. Yangi so‘z qo‘shishingiz mumkin.</div>`}`;}
function addModal(id){const c=state.cards.find(x=>x.id===id)||{word:'',translation:'',example:'',deck:decks()[0]||'Mening so‘zlarim',level:'B2'};openModal(id?'So‘zni tahrirlash':'Yangi so‘z qo‘shish',`<form id="word-form" class="form-grid"><label>Inglizcha so‘z yoki ibora<input name="word" required maxlength="120" value="${e(c.word)}" autofocus></label><label>O‘zbekcha tarjima<input name="translation" required maxlength="500" value="${e(c.translation)}"></label><label>To‘plam<input name="deck" required maxlength="80" list="deck-names" value="${e(c.deck)}"><datalist id="deck-names">${decks().map(d=>`<option value="${e(d)}">`).join('')}</datalist></label><label>Daraja<select name="level">${['A1','A2','B1','B2','C1','C2'].map(l=>`<option ${l===c.level?'selected':''}>${l}</option>`).join('')}</select></label><label class="full">Misol jumla (ixtiyoriy)<input name="example" maxlength="1000" value="${e(c.example)}"></label><div id="form-error" class="error full"></div><div class="buttons full"><button class="btn primary">Saqlash</button><button class="btn" type="button" data-action="close">Bekor qilish</button></div></form>`);$('#word-form').onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));for(const k in data)data[k]=data[k].trim();if(!data.word||!data.translation||!data.deck)return; if(state.cards.some(x=>x.id!==id&&normalize(x.word)===normalize(data.word)&&normalize(x.deck)===normalize(data.deck))){$('#form-error').textContent='Bu so‘z ushbu to‘plamda allaqachon mavjud.';return;}if(id)Object.assign(c,data);else state.cards.push({...data,id:uid(),reps:0,reviews:0,due:0,ease:2.5,interval:0});save();$('#modal').close();render();toast('So‘z saqlandi');};}
function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
function importModal(){openModal('Ko‘p so‘zni birga import qilish',`<p>Har qatorda <b>so‘z ; tarjima ; misol</b> yozing. Tab, « = » va « — » ajratgichlari ham qabul qilinadi. Excel’dan ikki ustunni nusxalashingiz mumkin.</p><form id="import-form"><label>To‘plam nomi<input name="deck" value="Mening so‘zlarim" required maxlength="80" style="width:100%;margin:8px 0 16px"></label><textarea name="text" placeholder="resilient ; bardoshli ; She is resilient.&#10;achieve ; erishmoq" required maxlength="200000"></textarea><input type="file" id="import-file" accept=".txt,.tsv,.csv" style="width:100%;margin-top:10px"><div class="notice">Bu import tayyor so‘z va tarjimalarni oladi. Avtomatik AI tarjimasi hali ulanmagan.</div><div class="error" id="import-error"></div><div class="buttons"><button class="btn primary">Import qilish</button><button class="btn" type="button" data-action="close">Bekor qilish</button></div></form>`);$('#import-file').onchange=async ev=>{const f=ev.target.files[0];if(f){if(f.size>200000){toast('Fayl 200 KB dan kichik bo‘lishi kerak');return;}$('#import-form textarea').value=await f.text();}};$('#import-form').onsubmit=ev=>{ev.preventDefault();const data=new FormData(ev.target),deck=String(data.get('deck')).trim(),{rows,errors}=parseWords(String(data.get('text')),deck);if(!deck)return;if(errors.length){$('#import-error').textContent=`${errors.join(', ')}-qatorni tekshiring: so‘z va tarjima kerak. Hech narsa import qilinmadi.`;return;}if(!rows.length)return;let count=0;for(const row of rows){if(state.cards.some(c=>normalize(c.word)===normalize(row.word)&&normalize(c.deck)===normalize(deck)))continue;state.cards.push({...row,id:uid(),reps:0,reviews:0,due:0,ease:2.5,interval:0});count++;}save();$('#modal').close();render();toast(`${count} ta so‘z qo‘shildi, ${rows.length-count} ta takroriy so‘z o‘tkazildi`);};}
function startStudy(deck=''){const cards=due().filter(c=>!deck||c.deck===deck);session={ids:cards.map(c=>c.id),index:0,done:0,deck};showBack=false;location.hash='study';if(route==='study')render();}
function study(){if(!session)return `<div class="empty"><h2>Mashg‘ulotni boshlang</h2>${btn('Takrorlashni boshlash','study','primary')}</div>`;if(session.index>=session.ids.length)return `<div class="empty"><span style="font-size:60px;color:var(--cyan)">✦</span><h1>${session.done?'Ajoyib natija!':'Hozircha hammasi tayyor!'}</h1><p>${session.done?`${session.done} ta kartochka takrorlandi. +${session.done*10} XP.`:'Bu to‘plamda hozir takrorlash vaqti kelgan so‘z yo‘q.'}</p><p>«Yana» deb baholangan so‘z 1 daqiqadan keyin navbatga qaytadi.</p><div class="buttons" style="justify-content:center">${btn('Bosh sahifa','home','primary')}${btn('Lug‘atga qaytish','vocab')}</div></div>`;const c=state.cards.find(c=>c.id===session.ids[session.index]);if(!c){session.index++;return study();}return heading('INTERVALLI TAKRORLASH','Har bir so‘z — yangi imkoniyat','Avval javobni eslashga harakat qiling, keyin ochib tekshiring.')+`<div class="study-top"><span>${e(c.deck)}</span><span>${session.index+1} / ${session.ids.length}</span></div><div class="progress" style="max-width:700px;margin:auto"><span style="width:${session.index/session.ids.length*100}%"></span></div><div class="flashcard"><span class="tag">${e(c.level)} · O‘ZBEKCHA → INGLIZCHA</span><h2 style="margin:35px 0 12px">${e(c.translation)}</h2>${showBack?`<div class="translation">${e(c.word)}</div><button class="icon-btn" data-audio="${e(c.word)}" aria-label="Talaffuzni eshitish">♫ Talaffuz</button><p>${e(c.example)}</p>`:'<p>Inglizchasini eslay olasizmi?</p>'}</div><div class="study-actions">${showBack?['again','hard','good','easy'].map((g,i)=>`<button class="btn ${i===2?'cyan':''}" data-grade="${g}"><span>${['Yana','Qiyin','Yaxshi','Oson'][i]}<small>${g==='again'?'1 daqiqa':schedule(c,g).interval+' kun'}</small></span></button>`).join(''):btn('Javobni ko‘rish ↵','flip','primary')}</div><p class="answer-hint">${showBack?'1–4 tugmalari bilan ham baholashingiz mumkin.':'Space yoki Enter bilan javobni oching.'}</p>`;}
function grade(g){if(!showBack||!session)return;const idx=state.cards.findIndex(c=>c.id===session.ids[session.index]);if(idx<0)return;state.cards[idx]=schedule(state.cards[idx],g);state.xp+=10;state.log[dateKey()]=(state.log[dateKey()]||0)+1;session.index++;session.done++;showBack=false;save();render();}
function startSpell(){spelling={ids:[...state.cards].sort(()=>Math.random()-.5).slice(0,10).map(c=>c.id),index:0,right:0,checked:false};location.hash='spell';if(route==='spell')render();}
function spell(){if(!spelling)return heading('TINGLANG. ESLANG. YOZING.','Imlo mashqi','Tarjimaga qarab inglizcha so‘zni yozing.')+`<section class="flashcard"><span style="font-size:50px;color:var(--purple)">⌨</span><h2 style="font-size:30px">Bilimingizni sinab ko‘ring</h2><p>Lug‘atingizdan 10 tagacha so‘z tanlanadi. Har to‘g‘ri javob uchun 5 XP.</p>${btn('Mashqni boshlash','spell-start','primary')}${!state.cards.length?'<p>Avval lug‘atga so‘z qo‘shing.</p>':''}</section>`;if(spelling.index>=spelling.ids.length)return `<div class="empty"><h1>Mashq yakunlandi ✦</h1><p>${spelling.right} / ${spelling.ids.length} to‘g‘ri javob · +${spelling.right*5} XP</p>${btn('Yana mashq qilish','spell-start','primary')} ${btn('Bosh sahifa','home')}</div>`;const c=state.cards.find(c=>c.id===spelling.ids[spelling.index]);if(!c){spelling.index++;return spell();}return heading('IMLO MASHQI',`${spelling.index+1} / ${spelling.ids.length} so‘z`,'Tarjimaga qarab inglizcha so‘z yoki iborani yozing.')+`<form id="spell-form" class="flashcard"><span class="tag">${e(c.deck)}</span><h2 class="translation" style="font-size:28px;margin-top:30px">${e(c.translation)}</h2><button class="text-btn" type="button" data-audio="${e(c.word)}">♫ Talaffuzni eshitish</button><input class="typing" id="spell-input" autocomplete="off" autocapitalize="off" spellcheck="false" required aria-label="Inglizcha javob" ${spelling.checked?'disabled':''}><div class="result" id="spell-result"></div>${spelling.checked?btn('Keyingi so‘z →','spell-next','primary'):'<button class="btn primary">Javobni tekshirish ↵</button>'}</form>`;}
const lessons=[{id:'context',title:'So‘zni kontekstda o‘rganish',tag:'LUG‘AT · 3 DAQIQA',text:'Yangi so‘zni yakka holda emas, jumlada o‘rganing. «Resilient» — qiyinchilikdan keyin tiklana oladigan. Masalan: “She remained resilient after the setback.” O‘zingizga tegishli bitta misol yozish so‘z bilan shaxsiy bog‘lanish yaratadi.',question:'Qaysi misolda “resilient” to‘g‘ri ishlatilgan?',answers:['She remained resilient after the setback.','She resilient to school yesterday.','I have two resilient.'],correct:0},{id:'collocations',title:'Birga ishlatiladigan so‘zlar',tag:'B2 · 4 DAQIQA',text:'Ingliz tilida ayrim so‘zlar tabiiy juftlik hosil qiladi. Masalan, “make a decision” (qaror qilmoq), “conduct research” (tadqiqot o‘tkazmoq) va “draw a conclusion” (xulosa chiqarmoq). Bularni to‘liq ibora sifatida kartochkaga yozing.',question:'“Qaror qilmoq” uchun to‘g‘ri birikmani tanlang.',answers:['do a decision','make a decision','take research'],correct:1},{id:'review',title:'Takrorlashni odatga aylantirish',tag:'SRS · 2 DAQIQA',text:'Takrorlash paytida avval javobni mustaqil eslashga harakat qiling. So‘ng inglizcha javobni ochib baholang. “Yana” — eslay olmadim; “Qiyin” — zo‘rg‘a esladim; “Yaxshi” — esladim; “Oson” — darhol esladim. Bahoni rost qo‘yish keyingi intervalni moslashtiradi.',question:'Javobni eslay olmasangiz qaysi bahoni tanlaysiz?',answers:['Oson','Yaxshi','Yana'],correct:2}];
function courses(){return heading('BILIMNI MUSTAHKAMLASH','Mini darslar','Lug‘at o‘rganish usullari bo‘yicha qisqa darslar va bitta savol.')+`<div class="cards">${lessons.map((l,i)=>`<button class="link-card" style="text-align:left" data-lesson="${l.id}"><span class="eyebrow">${l.tag}</span><div style="font-size:42px;color:var(--purple);margin:25px 0">0${i+1}</div><h3>${l.title}</h3><p>${state.completed.includes(l.id)?'✓ Tugallangan':'O‘qish va mashq qilish →'}</p></button>`).join('')}</div><div class="notice">Bu boshlang‘ich mini darslar. To‘liq CEFR kurslari va o‘qituvchi darslari uchun kontent hali qo‘shilmagan.</div>`;}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;openModal(l.title,`<p class="lesson-text">${l.text}</p><h3>${l.question}</h3><form id="quiz">${l.answers.map((a,i)=>`<label style="display:block;padding:10px 0"><input type="radio" name="answer" value="${i}" required> ${e(a)}</label>`).join('')}<div class="result" id="quiz-result"></div><button class="btn primary">Tekshirish</button></form>`);$('#quiz').onsubmit=ev=>{ev.preventDefault();const correct=Number(new FormData(ev.target).get('answer'))===l.correct;$('#quiz-result').textContent=correct?'To‘g‘ri! Dars tugallandi.':'Hali to‘g‘ri emas. Matnni qayta o‘qib ko‘ring.';if(correct&&!state.completed.includes(id)){state.completed.push(id);state.xp+=15;save();render();}};}
function analytics(){const history=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:d,n:state.log[dateKey(d)]||0};}),max=Math.max(1,...history.map(x=>x.n));return heading('O‘SISHINGIZ KO‘ZGUSI','Natijalar va statistika','Haqiqiy mashqlaringiz asosida hisoblangan shaxsiy natijalar.')+`<div class="stats">${stat('ϟ',state.xp,'Jami XP')}${stat('↻',Object.values(state.log).reduce((a,b)=>a+b,0),'Takrorlangan kartochkalar')}${stat('⌨',state.spell.total?Math.round(state.spell.right/state.spell.total*100)+'%':'—','Imlo aniqligi')}${stat('♨',streak(state.log),'Ketma-ket kunlar')}</div><div class="grid"><section class="panel"><h2>Oxirgi 7 kun</h2><p style="font-size:11px">Kuniga takrorlangan kartochkalar soni</p><div class="chart">${history.map(h=>`<div class="bar-wrap"><span>${h.n}</span><div class="bar" style="height:${h.n/max*125}px"></div><span>${h.date.toLocaleDateString('uz-UZ',{day:'numeric',month:'short'})}</span></div>`).join('')}</div></section><section class="panel"><h2>To‘plamlar bo‘yicha</h2>${decks().map(d=>{const cs=state.cards.filter(c=>c.deck===d),n=cs.filter(c=>c.reps>0).length;return `<div style="margin-top:22px"><div class="goal-row"><span>${e(d)}</span><b>${n} / ${cs.length}</b></div><div class="progress"><span style="width:${n/cs.length*100}%"></span></div></div>`;}).join('')}</section></div><div class="notice">Umumiy reyting server va foydalanuvchi hisoblari ulangandan so‘ng qo‘shiladi. Hozir boshqa o‘quvchilar uchun soxta natijalar ko‘rsatilmaydi.</div>`;}
function telegram(){return heading('O‘QISH HAR DOIM YONINGIZDA','Telegram integratsiyasi','Bot va Mini App uchun keyingi ulanish bosqichi.')+`<div class="grid"><section class="panel"><span style="font-size:48px;color:var(--cyan)">➤</span><h2 style="margin-top:20px">Bir lug‘at. Ikki qulay muhit.</h2><p>Rejalashtirilgan imkoniyatlar: kundalik eslatma, Telegram’dan kartochka takrorlash va veb-versiya bilan sinxronlash.</p><span class="tag">Hali ulanmagan</span><div class="notice">Haqiqiy ulanish uchun bot, xavfsiz server va foydalanuvchini Telegram orqali tekshirish kerak. Bot tokenini chatga yoki sayt kodiga joylamang.</div></section><section class="panel"><h2>Ulanish ketma-ketligi</h2>${['Bot nomi va vazifasini kelishamiz','Telegram Mini App manzilini sozlaymiz','Kirish va xavfsiz initData tekshiruvini qo‘shamiz','So‘zlar va SRS jadvalini serverda sinxronlaymiz','Vaqt mintaqasiga mos eslatmalarni yoqamiz'].map((t,i)=>`<div class="lesson-item"><span>${i+1}. ${t}</span></div>`).join('')}</section></div>`;}
let designs=[];
async function loadDesigns(){try{designs=await (await fetch('designs.json')).json();if(route==='designs')render();}catch{}}
function designView(){return heading('SIZ YUBORGAN STITCH MANBALARI','Dizaynlar kutubxonasi','Asl ekranlar taqqoslash uchun saqlandi. Ular alohida dizayn namunalari.')+`<div class="cards">${designs.map(d=>`<a class="link-card" href="${e(d.path)}" target="_blank" rel="noopener"><img src="${e(d.image)}" alt="${e(d.name)}" loading="lazy"><h3>${e(d.name)}</h3><span class="text-btn">Asl ekran ↗</span></a>`).join('')}</div>`;}
function settings(){return heading('O‘ZINGIZGA MOSLANG','Sozlamalar','Profil, kunlik maqsad va ma’lumotlaringiz.')+`<div class="settings-grid"><section class="panel"><h2>Shaxsiy sozlamalar</h2><form id="settings-form"><label>Ismingiz<input name="name" value="${e(state.name)}" maxlength="40" required></label><label>Kunlik maqsad (kartochka)<input name="goal" type="number" value="${state.goal}" min="1" max="500" required></label><button class="btn primary">Saqlash</button></form></section><section class="panel"><h2>Ma’lumotlar sizniki</h2><p>So‘zlar va natijalar hozir shu qurilmaning brauzerida saqlanadi. Boshqa qurilmada avtomatik ko‘rinmaydi. Vaqti-vaqti bilan zaxira yuklab oling.</p><div class="buttons">${btn('↓ Zaxira nusxasi','export')}${btn('↥ Zaxiradan tiklash','restore')}</div><p class="callout">${storageOK?'Brauzer xotirasiga saqlash faol.':'Saqlashda muammo bor. Zaxira oling.'}</p></section></div><div class="notice">Hozirgi versiya: funksional MVP. Foydalanuvchi hisoblari, o‘qituvchi/admin rollari, bulut sinxronlash va AI xizmatlari hali ulanmagan.</div>`;}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`lexora-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function restore(){openModal('Zaxira nusxasini tiklash','<p>Lexora JSON zaxirasini tanlang. Tiklash joriy so‘zlar va natijalarni almashtiradi.</p><input type="file" id="backup-file" accept=".json"><p id="backup-result" class="error"></p>');$('#backup-file').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Fayl juda katta.');const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.cards)||data.cards.length>10000||typeof data.name!=='string'||!Number.isFinite(data.goal)||data.goal<1||data.goal>500||!Number.isFinite(data.xp)||data.xp<0||!data.log||!data.spell||!Array.isArray(data.completed))throw Error('Lexora zaxirasi formati noto‘g‘ri.');const ids=new Set();for(const c of data.cards){if(typeof c.id!=='string'||ids.has(c.id)||!['word','translation','deck','level','example'].every(k=>typeof c[k]==='string')||!['due','reps','reviews','interval','ease'].every(k=>Number.isFinite(c[k])&&c[k]>=0))throw Error('Kartochkalar formati noto‘g‘ri.');ids.add(c.id);}if(Object.values(data.log).some(v=>!Number.isInteger(v)||v<0)||!Number.isInteger(data.spell.right)||!Number.isInteger(data.spell.total)||data.spell.right<0||data.spell.total<data.spell.right)throw Error('Statistika formati noto‘g‘ri.');$('#backup-result').className='success';$('#backup-result').textContent=`${data.cards.length} ta so‘z topildi.`;const b=document.createElement('button');b.className='btn primary';b.textContent='Tasdiqlash va tiklash';b.onclick=()=>{state=data;session=null;spelling=null;save();$('#modal').close();render();toast('Zaxira tiklandi');};$('#modal-body').append(b);}catch(err){$('#backup-result').textContent=err.message;}};}
function render(){const pages={home,vocab,study,spell,courses,analytics,telegram,settings,designs:designView};$('#app').innerHTML=(pages[route]||home)();$('#page-name').textContent=nav.find(n=>n[0]===route)?.[2]||(route==='study'?'Takrorlash':'Bosh sahifa');$('#nav').innerHTML=nav.map(([id,icon,title,badge])=>`<a href="#${id}" class="${route===id||route==='study'&&id==='vocab'?'active':''}" ${route===id?'aria-current="page"':''}><span class="icon">${icon}</span>${title}${badge?`<span class="badge">${badge}</span>`:''}</a>`).join('');updateHeader();if(route==='vocab'){$('#search').oninput=ev=>{search=ev.target.value;$('#word-table').innerHTML=wordTable();};$('#deck-filter').onchange=ev=>{deckFilter=ev.target.value;$('#word-table').innerHTML=wordTable();};}if(route==='spell'&&$('#spell-form')){const input=$('#spell-input');if(!spelling.checked)input.focus({preventScroll:true});$('#spell-form').onsubmit=ev=>{ev.preventDefault();if(spelling.checked)return;const c=state.cards.find(c=>c.id===spelling.ids[spelling.index]),correct=normalize(input.value)===normalize(c.word);spelling.checked=true;spelling.right+=correct?1:0;state.spell.total++;state.spell.right+=correct?1:0;state.xp+=correct?5:0;save();const val=input.value;render();$('#spell-input').value=val;$('#spell-result').textContent=correct?'✓ To‘g‘ri! +5 XP':`To‘g‘ri javob: ${c.word}`;$('#spell-result').style.color=correct?'var(--cyan)':'var(--orange)';};}if(route==='settings')$('#settings-form').onsubmit=ev=>{ev.preventDefault();const data=new FormData(ev.target),name=String(data.get('name')).trim();if(!name)return;state.name=name;state.goal=Number(data.get('goal'));save();toast('Sozlamalar saqlandi');render();};}
document.addEventListener('click',ev=>{const t=ev.target.closest('button,a');if(!t)return;if(t.dataset.route){location.hash=t.dataset.route;}if(t.dataset.study!==undefined){startStudy(t.dataset.study);}if(t.dataset.edit)addModal(t.dataset.edit);if(t.dataset.delete){const c=state.cards.find(c=>c.id===t.dataset.delete);openModal('So‘zni o‘chirish',`<p>«${e(c.word)}» so‘zini o‘chirasizmi?</p><button class="btn danger" id="confirm-delete">O‘chirish</button>`);$('#confirm-delete').onclick=()=>{state.cards=state.cards.filter(x=>x.id!==c.id);save();$('#modal').close();render();};}if(t.dataset.audio){if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t.dataset.audio);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u);}else toast('Bu brauzer talaffuzni qo‘llamaydi');}if(t.dataset.grade)grade(t.dataset.grade);if(t.dataset.lesson)lesson(t.dataset.lesson);const actions={add:()=>addModal(),import:importModal,close:()=>$('#modal').close(),study:()=>startStudy(),flip:()=>{showBack=true;render();},'spell-start':()=>state.cards.length?startSpell():toast('Avval so‘z qo‘shing'),'spell-next':()=>{if(!spelling?.checked)return;spelling.index++;spelling.checked=false;render();},export:exportData,restore,home:()=>location.hash='home',vocab:()=>location.hash='vocab'};actions[t.dataset.action]?.();});
document.addEventListener('keydown',ev=>{if($('#modal').open||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName))return;if(route==='study'&&session){if((ev.code==='Space'||ev.key==='Enter')&&!showBack){ev.preventDefault();showBack=true;render();}else if(showBack&&['1','2','3','4'].includes(ev.key)){grade(['again','hard','good','easy'][Number(ev.key)-1]);}}});
$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');document.addEventListener('click',ev=>{if(!ev.target.closest('.sidebar')&&!ev.target.closest('#menu'))$('.sidebar').classList.remove('open');});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';$('.sidebar').classList.remove('open');render();window.scrollTo(0,0);});
route=location.hash.slice(1)||'home';render();loadDesigns();
